"""Integer membership for longitudinal separator sides, independent of geometry.

Grants retain actual original Street IDs. Joining temporary rows and accumulating
by INT group IDs selects all routes of those Streets, including unlisted routes
that must make the completeness proof fail. Semantic IDs never become positions.
"""
from . import curved_network_ownership_nodes as own
from . import curved_junction_nodes as boundary

c = boundary.c


def routes(g, source, street_field, grants):
    members = c._store(g, grants, '_sm_id', c.named(g, 'st_sr_street_id', 'INT'), 'INT')
    members = c._store(g, members, '_sm_grant', 1, 'INT')
    members = c._store(g, members, '_sm_route', 0, 'INT')
    source = c._store(g, source, '_sm_id', c.named(g, street_field, 'INT'), 'INT')
    source = c._store(g, source, '_sm_grant', 0, 'INT')
    source = c._store(g, source, '_sm_route', 1, 'INT')
    sentinel = c._store(g, c._line(g, 1), '_sm_id', -1, 'INT')
    sentinel = c._store(g, sentinel, '_sm_grant', 0, 'INT')
    sentinel = c._store(g, sentinel, '_sm_route', 0, 'INT')
    joined = boundary._join(g, source, members, sentinel)
    total = own._total(g, c.named(g, '_sm_grant', 'INT'), c.named(g, '_sm_id', 'INT'))
    return c._select(g, joined, c.named(g, '_sm_route', 'INT')*own._compare(g, total, 0, 'GREATER_THAN'))


def valid(g, rules):
    """Both sides have disjoint real Street identities; patch rules have none."""
    kind = c.named(g, 'st_sr_kind', 'INT'); sid = c.named(g, 'st_sr_street_id', 'INT')
    role = c.named(g, 'st_sr_role', 'INT')
    is_route = 1.-own._compare(g, kind, 0)
    left = own._total(g, is_route*own._compare(g, role, 0), sid)
    right = own._total(g, is_route*own._compare(g, role, 1), sid)
    check = c.choose(g, is_route, own._compare(g, sid, 0, 'GREATER_EQUAL')*
                     own._compare(g, left*right, 0), own._compare(g, sid, -1))
    return own._all(g, rules, own._exists(g, ['st_sr_street_id'])*check)


def ports_valid(g, members, original):
    compare = lambda a, b, op='EQUAL': own._compare(g, a, b, op)
    check = 1.
    for field in ('start_index', 'end_index'):
        port = c.named(g, 'st_cs_'+field, 'INT')
        check = check*compare(port, 0, 'GREATER_EQUAL')*compare(port, c._count(g, original), 'LESS_THAN')
        check = check*compare(c._read(g, original, 'st_cj_street_id', port, 'INT'), c.named(g, 'st_cs_street_id', 'INT'))
    check = check*(1.-compare(c.named(g, 'st_cs_start_index', 'INT'), c.named(g, 'st_cs_end_index', 'INT')))
    return own._all(g, members, check)
